components.css:
.ds-btn-primary{display:inline-flex;align-items:center;justify-content:center;gap:8px;font-family:'Outfit Variable', Outfit, system-ui, -apple-system, 'Segoe UI', sans-serif;font-size:1rem;font-weight:600;color:var(--accent-ink,#ffffff);background:var(--accent,#2e7d46);border:1px solid transparent;border-radius:999px;padding:12px 24px;cursor:pointer;transition:transform 120ms cubic-bezier(0.23, 1, 0.32, 1),background-color 160ms cubic-bezier(0.23, 1, 0.32, 1)}
.ds-btn-primary:hover{background:var(--accent-strong,#256638)}
.ds-btn-primary:active{transform:scale(0.97)}
.ds-btn-primary:focus-visible{outline:2px solid var(--accent,#2e7d46);outline-offset:2px}

.ds-btn-secondary{display:inline-flex;align-items:center;justify-content:center;gap:8px;font-family:'Outfit Variable', Outfit, system-ui, -apple-system, 'Segoe UI', sans-serif;font-size:1rem;font-weight:600;color:var(--ink,#17251a);background:var(--surface,#ffffff);border:1px solid var(--line-strong,#c9d4c5);border-radius:999px;padding:12px 24px;cursor:pointer;transition:transform 120ms cubic-bezier(0.23, 1, 0.32, 1),background-color 160ms cubic-bezier(0.23, 1, 0.32, 1)}
.ds-btn-secondary:hover{background:var(--surface-2,#eff4ec)}
.ds-btn-secondary:active{transform:scale(0.97)}
.ds-btn-secondary:focus-visible{outline:2px solid var(--accent,#2e7d46);outline-offset:2px}

.ds-btn-ghost{display:inline-flex;align-items:center;justify-content:center;gap:8px;font-family:'Outfit Variable', Outfit, system-ui, -apple-system, 'Segoe UI', sans-serif;font-size:1rem;font-weight:600;color:var(--accent,#2e7d46);background:transparent;border:1px solid color-mix(in srgb, var(--accent,#2e7d46) 45%, transparent);border-radius:999px;padding:12px 24px;cursor:pointer;transition:transform 120ms cubic-bezier(0.23, 1, 0.32, 1),background-color 160ms cubic-bezier(0.23, 1, 0.32, 1),color 160ms cubic-bezier(0.23, 1, 0.32, 1)}
.ds-btn-ghost:hover{background:var(--accent-soft,#e7f2ea);color:var(--accent-strong,#256638)}
.ds-btn-ghost:active{transform:scale(0.97)}
.ds-btn-ghost:focus-visible{outline:2px solid var(--accent,#2e7d46);outline-offset:2px}

.ds-field{display:flex;flex-direction:column;gap:6px}
.ds-field-label{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:0.7rem;letter-spacing:0.07em;text-transform:uppercase;color:var(--ink-soft,#4a5a4d)}
.ds-input{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:0.95rem;color:var(--ink,#17251a);background:var(--bg,#f7f9f5);border:1px solid var(--line-strong,#c9d4c5);border-radius:10px;padding:10px 12px;min-width:130px;transition:border-color 160ms cubic-bezier(0.23, 1, 0.32, 1)}
.ds-input::placeholder{color:var(--placeholder,#647266)}
.ds-input:focus{border-color:var(--accent,#2e7d46);outline:none;box-shadow:0 0 0 3px color-mix(in srgb, var(--accent,#2e7d46) 22%, transparent)}
.ds-input:focus-visible{caret-color:var(--accent,#2e7d46)}

.ds-chips{display:flex;gap:8px;flex-wrap:wrap}
.ds-chip{font-family:'Outfit Variable', Outfit, system-ui, -apple-system, 'Segoe UI', sans-serif;font-size:0.88rem;font-weight:580;color:var(--ink-soft,#4a5a4d);background:var(--surface,#ffffff);border:1px solid var(--line-strong,#c9d4c5);border-radius:999px;padding:7px 15px;cursor:pointer;transition:background-color 160ms cubic-bezier(0.23, 1, 0.32, 1),color 160ms cubic-bezier(0.23, 1, 0.32, 1),border-color 160ms cubic-bezier(0.23, 1, 0.32, 1),transform 120ms cubic-bezier(0.23, 1, 0.32, 1)}
.ds-chip:hover{border-color:var(--accent,#2e7d46);color:var(--accent,#2e7d46)}
.ds-chip:active{transform:scale(0.97)}
.ds-chip.is-active{background:var(--accent,#2e7d46);border-color:var(--accent,#2e7d46);color:var(--accent-ink,#ffffff)}
.ds-chip:focus-visible{outline:2px solid var(--accent,#2e7d46);outline-offset:2px}

.ds-nav{position:sticky;top:0;z-index:50;background:color-mix(in srgb, var(--surface,#ffffff) 86%, transparent);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid var(--line,#e2e9df)}
.ds-nav-inner{max-width:1200px;margin:0 auto;height:68px;padding:0 24px;display:flex;align-items:center;gap:28px}
.ds-brand{display:inline-flex;align-items:center;gap:10px;color:var(--ink,#17251a);text-decoration:none;font-weight:640;font-size:1.06rem;letter-spacing:-0.01em}
.ds-brand svg{color:var(--accent,#2e7d46);flex:none}
.ds-nav-links{display:flex;gap:4px;margin-left:8px;flex:1}
.ds-nav-links a{color:var(--ink-soft,#4a5a4d);text-decoration:none;font-size:0.95rem;font-weight:520;padding:8px 12px;border-radius:999px;transition:background-color 160ms cubic-bezier(0.23, 1, 0.32, 1),color 160ms cubic-bezier(0.23, 1, 0.32, 1)}
.ds-nav-links a:hover{background:var(--surface-2,#eff4ec);color:var(--ink,#17251a)}
.ds-nav-links a:focus-visible{outline:2px solid var(--accent,#2e7d46);outline-offset:2px;border-radius:4px}
.ds-net-pill{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:0.72rem;letter-spacing:0.04em;text-transform:uppercase;padding:5px 10px;border-radius:999px;background:var(--accent-soft,#e7f2ea);color:var(--accent-strong,#256638);border:1px solid color-mix(in srgb, var(--accent,#2e7d46) 30%, transparent)}

.ds-task-list{list-style:none;margin:0;padding:0;background:var(--surface,#ffffff);border:1px solid var(--line,#e2e9df);border-radius:16px;overflow:hidden}
.ds-task{display:flex;align-items:flex-start;gap:12px;padding:14px 18px;border-bottom:1px solid var(--line,#e2e9df)}
.ds-task:last-child{border-bottom:0}
.ds-task-box{width:22px;height:22px;flex:none;border:2px solid var(--line-strong,#c9d4c5);border-radius:7px;margin-top:2px;display:inline-flex;align-items:center;justify-content:center;color:transparent;cursor:pointer;transition:background-color 160ms cubic-bezier(0.23, 1, 0.32, 1),border-color 160ms cubic-bezier(0.23, 1, 0.32, 1),transform 120ms cubic-bezier(0.23, 1, 0.32, 1),color 160ms cubic-bezier(0.23, 1, 0.32, 1)}
.ds-task-box:hover{border-color:var(--accent,#2e7d46)}
.ds-task-box:active{transform:scale(0.92)}
.ds-task.is-done .ds-task-box{background:var(--accent,#2e7d46);border-color:var(--accent,#2e7d46);color:var(--accent-ink,#ffffff)}
.ds-task-box:focus-visible{outline:2px solid var(--accent,#2e7d46);outline-offset:2px}
.ds-task-body{min-width:0}
.ds-task-name{font-weight:600;display:block;transition:color 160ms cubic-bezier(0.23, 1, 0.32, 1)}
.ds-task.is-done .ds-task-name{color:var(--ink-soft,#4a5a4d);text-decoration:line-through}
.ds-task-meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}
.ds-meta-chip{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:0.7rem;letter-spacing:0.03em;color:var(--ink-soft,#4a5a4d);background:var(--surface-2,#eff4ec);border:1px solid var(--line,#e2e9df);border-radius:999px;padding:3px 9px}
.ds-meta-chip.is-frost{color:var(--stamp,#c0392b);border-color:color-mix(in srgb, var(--stamp,#c0392b) 40%, transparent);background:color-mix(in srgb, var(--stamp,#c0392b) 8%, transparent)}

.ds-plan-card{position:relative;background:var(--surface,#ffffff);border:1.5px solid var(--ink,#17251a);border-radius:16px;padding:18px 20px 16px;box-shadow:0 2px 4px rgba(23,37,26,0.06),0 10px 24px rgba(23,37,26,0.12)}
.ds-plan-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}
.ds-stamp{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:0.7rem;font-weight:500;letter-spacing:0.08em;text-transform:uppercase;border:1.5px solid var(--stamp,#c0392b);color:var(--stamp,#c0392b);padding:4px 9px;border-radius:4px;transform:rotate(-1.5deg);white-space:nowrap}
.ds-place{font-size:0.9rem;font-weight:600;color:var(--ink-soft,#4a5a4d)}
.ds-plan-rows{border-top:1px solid var(--line,#e2e9df)}
.ds-plan-row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid var(--line,#e2e9df)}
.ds-plan-label{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:0.72rem;letter-spacing:0.06em;text-transform:uppercase;color:var(--ink-soft,#4a5a4d);padding-top:3px}
.ds-plan-value{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:1.02rem;font-weight:500;text-align:right}
.ds-plan-row.is-task .ds-plan-value{color:var(--accent,#2e7d46)}
.ds-plan-note{margin-top:10px;font-size:0.78rem;color:var(--ink-soft,#4a5a4d)}

.ds-titleblock{display:grid;grid-template-columns:repeat(4,1fr);background:var(--surface,#ffffff);border:1.5px solid var(--ink,#17251a);border-radius:16px;overflow:hidden}
.ds-tb-cell{padding:18px 20px;border-right:1px solid var(--line,#e2e9df);display:flex;flex-direction:column;gap:8px;min-width:0}
.ds-tb-cell:last-child{border-right:0}
.ds-tb-label{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:0.7rem;letter-spacing:0.09em;text-transform:uppercase;color:var(--ink-soft,#4a5a4d)}
.ds-tb-value{font-size:0.98rem;color:var(--ink,#17251a);overflow-wrap:anywhere}
.ds-tb-big{font-family:'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;font-size:clamp(1.25rem,2.2vw,1.6rem);font-weight:500;letter-spacing:-0.01em}
@media (max-width:960px){.ds-titleblock{grid-template-columns:repeat(2,1fr)}.ds-tb-cell:nth-child(2n){border-right:0}}
